import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import './event-list.css';

export interface EventListItem {
  /** Stable across status updates, reordering and temporary filtering. */
  id: string;
  title: ReactNode;
  description?: ReactNode;
  timestamp: ReactNode;
  dateTime?: string;
  icon?: ReactNode;
  status?: { label: string; tone?: 'neutral' | 'success' | 'error' | 'pending' };
  actionLabel?: string;
  disabled?: boolean;
}
export interface EventListProps {
  items: readonly EventListItem[];
  label?: string;
  emptyMessage?: ReactNode;
  onItemAction?: (id: string) => void;
  selectedId?: string;
  className?: string;
}

/** Initial items are visible. Only IDs first seen after mount receive an entrance. */
export function EventList({ items, label = 'Activity', emptyMessage = 'No activity yet.',
  onItemAction, selectedId, className = '' }: EventListProps) {
  const seen = useRef(new Set(items.map(item => item.id)));
  const insertion = useRef(0);
  const insertionVersion = insertion.current + (items.some(item => !seen.current.has(item.id)) ? 1 : 0);
  const reducedMotion = useReducedMotion();
  useLayoutEffect(() => {
    insertion.current = insertionVersion;
    for (const item of items) seen.current.add(item.id);
  }, [items, insertionVersion]);
  // The reference grows new cards without a visible overshoot. Position-only
  // layout keeps existing text at its native size while it makes room.
  const entrance = reducedMotion ? { duration: 0 } : { type: 'spring' as const, stiffness: 420, damping: 46 };
  return <ol className={`mf-event-list ${className}`} aria-label={label}>
    {!items.length && <li className="mf-event-list__empty">{emptyMessage}</li>}
    {items.map(item => <motion.li key={item.id} data-event-id={item.id}
      className="mf-event-list__slot" layout={!reducedMotion && 'position'}
      layoutDependency={insertionVersion} initial={false} transition={entrance}>
      <motion.div className="mf-event-list__row" data-selected={selectedId === item.id || undefined}
        initial={!reducedMotion && !seen.current.has(item.id) ? { opacity: 0, scale: 0 } : false}
        animate={{ opacity: 1, scale: 1 }} transition={entrance}>
      <span className="mf-event-list__icon" data-tone={item.status?.tone ?? 'neutral'} aria-hidden="true">{item.icon ?? <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M4 5h12M4 10h8M4 15h10"/><circle cx="16" cy="14" r="2"/></svg>}</span>
      <div className="mf-event-list__body"><div className="mf-event-list__heading"><span className="mf-event-list__title">{item.title}</span><time dateTime={item.dateTime}>{item.timestamp}</time></div>
        {item.description && <p className="mf-event-list__description">{item.description}</p>}
        {item.status && <span className="mf-event-list__status" data-tone={item.status.tone ?? 'neutral'}>{item.status.label}</span>}
      </div>
      {onItemAction && <button type="button" className="mf-event-list__action" aria-label={item.actionLabel ?? `View event ${item.id}`} disabled={item.disabled}
        aria-pressed={selectedId === item.id} onClick={() => onItemAction(item.id)}>
        <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m8 5 5 5-5 5"/></svg>
      </button>}
      </motion.div>
    </motion.li>)}
  </ol>;
}

.mf-event-list { --mf-ink:#262626; --mf-muted:#6b7280; margin:0; padding:0; list-style:none; color:var(--mf-ink); display:flex; flex-direction:column; gap:8px; font:13px/1.45 Inter,system-ui,sans-serif; }
.mf-event-list__slot { min-width:0; }
.mf-event-list__row { display:flex; align-items:center; gap:11px; padding:12px; border:1px solid transparent; border-radius:12px; background:#fff; box-shadow:0 0 0 1px rgb(0 0 0 / .03),0 2px 4px rgb(0 0 0 / .05),0 12px 24px rgb(0 0 0 / .05); min-width:0; transform-origin:center; }
.mf-event-list__row[data-selected] { background:#eff6ff; border-color:#1e86ff; }
.mf-event-list__icon { width:32px; height:32px; flex:0 0 32px; display:grid; place-items:center; background:#1e86ff; border-radius:9px; color:#102a43; }
.mf-event-list__icon[data-tone=success] { background:#00c9a7; color:#003d33; }
.mf-event-list__icon[data-tone=pending] { background:#ffb800; color:#5c3d00; }
.mf-event-list__icon[data-tone=error] { background:#ff3d71; color:#600023; }
.mf-event-list__icon svg { width:18px; height:18px; }
.mf-event-list__body { min-width:0; flex:1; }
.mf-event-list__heading { display:flex; align-items:baseline; justify-content:space-between; gap:12px; }
.mf-event-list__title { font-weight:550; overflow-wrap:anywhere; }
.mf-event-list__heading time { font-size:11px; color:var(--mf-muted); flex-shrink:0; font-variant-numeric:tabular-nums; }
.mf-event-list__row[data-selected] time { color:#4b5563; }
.mf-event-list__description { margin:2px 0 0; color:var(--mf-ink); font-size:12px; overflow-wrap:anywhere; }
.mf-event-list__status { display:inline-flex; align-items:center; gap:5px; margin-top:5px; color:#4b5563; font-size:11px; }
.mf-event-list__status::before { content:''; width:5px; height:5px; border-radius:50%; background:currentColor; }
.mf-event-list__status[data-tone=success] { color:#047857; }
.mf-event-list__status[data-tone=error] { color:#be123c; }
.mf-event-list__status[data-tone=pending] { color:#92400e; }
.mf-event-list__action { border:0; padding:6px; width:30px; height:30px; display:grid; place-items:center; color:#6b7280; background:transparent; border-radius:7px; cursor:pointer; flex-shrink:0; transition:background 140ms,color 140ms; }
.mf-event-list__action svg { width:18px; height:18px; }
.mf-event-list__action:hover:not(:disabled) { background:#f3f4f6; color:#262626; }
.mf-event-list__action:focus-visible { outline:2px solid #2563eb; outline-offset:3px; }
.mf-event-list__action:disabled { color:#6b7280; background:#f3f4f6; cursor:not-allowed; }
.mf-event-list__empty { padding:24px 12px; color:var(--mf-muted); text-align:center; border:1px dashed #d1d5db; border-radius:12px; }
@media(max-width:480px) { .mf-event-list__heading { flex-wrap:wrap; gap:2px 10px; } .mf-event-list__row { padding:10px; gap:8px; } }
@media(prefers-reduced-motion:reduce) { .mf-event-list__action { transition:none; } }
